
/* Charlotte AI V10 — actionable production experience. Browser-only demonstration.
  Content suggestions are keyword-based, not audio transcription, image recognition or a live AI call. */
const v10PreviousRender = render;
const v10PreviousDrafts = viewDrafts;
const v10PreviousAssets = viewAssets;
const v10PreviousRecord = viewRecord;
const v10PreviousStories = viewStories;
const v10PreviousReview = viewReview;
const v10PreviousDrawer = renderDrawer;
const v10PreviousSaveStory = saveStory;
const v10PreviousProcessFiles = processFiles;
const v10PreviousAttachPostFile = caAttachPostFile;
const v10PreviousUpdatePost = updatePost;
let v10EditingPost = null, v10SuggestOpen = false, v10PreviewMode = '', v10StoryFiles = [], v10SuggestionFiles = [];

function v10Normalize(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() }
function v10SuggestionsFor(text, format) {
  const s = v10Normalize(text), f = v10Normalize(format), a = [];
  if (/dad|father|parent|family|olympic/.test(s)) a.push('Family or father-related photograph');
  if (/hurd|track|athlet|sport|marathon|race|hyrox|training/.test(s)) a.push('Relevant athletics or race photograph/footage');
  if (/adhd|brain|workload|social media|office|desk|burnout/.test(s)) a.push('Candid working or behind-the-scenes moment');
  if (/dog|martin|puppy|pet/.test(s)) a.push('Dog photo or short video');
  if (/event|conference|founder|startup|crowdclip|business/.test(s)) a.push('Founder, team or event visual');
  if (/reel|video/.test(f)) a.push('Vertical footage suitable for a Reel');
  else if (/story/.test(f)) a.push('Vertical Story photo or video');
  else if (/carousel/.test(f)) a.push('Sequence of images for the carousel');
  else a.push('Primary photo for the post');
  return [...new Set(a)].slice(0, 3);
}
function v10MatchName(asset, media) {
  const terms = v10Normalize(asset).split(' ').filter(w => w.length > 3 && !['photo', 'video', 'vertical', 'relevant', 'footage', 'short', 'suitable', 'behind', 'scenes', 'moment', 'image', 'primary', 'visual'].includes(w));
  const hay = v10Normalize([media.name, media.tag].join(' ')); return terms.some(t => hay.includes(t));
}
function v10ScanOne(p) {
  const linked = (state.stories || []).find(s => String(s.id) === String(p.storyId));
  const desc = [p.title, p.caption, p.theme, linked?.text].join(' ');
  const next = v10SuggestionsFor(desc, p.format);
  const manual = (p.assets || []).filter(a => a.origin !== 'demo-rule');
  const prior = (p.assets || []).filter(a => a.origin === 'demo-rule');
  const existing = [...manual.map(x => v10Normalize(x.name))];
  const auto = (manual.length || p.mediaId ? [] : next.slice(0, 2)).filter(x => !existing.some(y => y === v10Normalize(x))).map(name => {
    const old = prior.find(x => x.name === name), matches = state.media.filter(m => v10MatchName(name, m)).slice(0, 3);
    return { name, status: old?.status || 'missing', origin: 'demo-rule', basis: 'Post theme, caption and format', possibleMatches: matches.map(x => x.name) };
  });
  p.assets = manual.concat(auto);
  return auto.length;
}
function v10ScanAll(notify = true) {
  let n = 0; state.posts.forEach(p => n += v10ScanOne(p));
  state.stories.forEach(s => { s.assetSuggestions = v10SuggestionsFor([s.title, s.text, s.theme].join(' '), '') });
  state.v10ScanVersion = 1; save(); if (notify) { render(); toast('Demo rules refreshed suggestions for ' + state.posts.length + ' drafts. Charlotte must confirm matches.'); } return n;
}
function v10ManualAssetRequest() { const p = state.posts.find(x => x.id === activePostId); if (!p) return; const name = prompt('What photo, video or other media is needed for this post?'); if (!name?.trim()) return; p.assets ??= []; p.assets.push({ name: name.trim(), status: 'missing', origin: 'charlotte', basis: 'Requested by Charlotte' }); save(); renderDrawer(); toast('Manual asset request added') }
function v10TargetCard(n) { if (n === 0) { filter = 'ready'; go('drafts') } else if (n === 1) { filter = 'pending'; go('drafts') } else if (n === 2) { go('operations') } else if (n === 3) { go('assets') } }
render = function () {
  v10PreviousRender(); if (role === 'charlotte' && page === 'overview') {
    const names = ['Approved & scheduled', 'Awaiting Naomi', 'Content health', 'Missing assets'];
    document.querySelectorAll('.stat-grid .stat').forEach((e, i) => { if (i > 3) return; e.classList.add('v10-stat-link'); e.setAttribute('role', 'button'); e.setAttribute('tabindex', '0'); e.setAttribute('aria-label', 'Open ' + names[i]); e.title = 'Open ' + names[i]; if (!e.querySelector('.v10-stat-arrow')) e.insertAdjacentHTML('beforeend', '<span class="v10-stat-arrow" aria-hidden="true">↗</span>'); e.onclick = () => v10TargetCard(i); e.onkeydown = ev => { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); v10TargetCard(i) } } });
  }
};
viewDrafts = function () { if (filter !== 'ready') return v10PreviousDrafts(); const posts = state.posts.filter(p => ['approved', 'scheduled'].includes(p.status)); return `${head('Approved & scheduled', 'Ready-to-publish drafts, clearly separated from posts awaiting revision.', `<button class="btn outline" onclick="filter='all';render()">Show all posts</button>`)}<div class="v10-data-note">Only Naomi-approved drafts can be marked scheduled. This demo does not publish automatically.</div><div class="card cardpad"><div class="flex-between" style="margin-bottom:14px"><strong>${posts.length} approved / scheduled posts</strong><button class="btn small outline" onclick="filter='all';render()">All statuses ↗</button></div>${postList(posts)}</div>` };
viewAssets = function () {
  let base = v10PreviousAssets(); const extra = `<div class="v10-scan-row"><div><h3>Charlotte AI · Missing-media suggestions</h3><p>Automatically suggests media from the story/caption/theme and searches <b>filenames and tags</b> for potential matches. It does not understand the actual contents of photos or videos yet; Charlotte must confirm or correct every suggested requirement.</p></div><button class="btn primary" onclick="v10ScanAll()">✦ Refresh media-gap suggestions</button></div>`; const unconfirmed = state.posts.flatMap(post => (post.assets || []).filter(a => a.origin === 'demo-rule' && a.status === 'missing').map(a => ({ post, a })));
  const cards = `<section class="card cardpad spaced"><div class="card-header"><h3>Automatic suggestions to verify</h3><span class="pill pending">${unconfirmed.length} needs review</span></div><p class="v10-upload-note">These are rule-generated prompts based on text, not real media recognition. Potential matches are based only on filenames and tags.</p>${unconfirmed.length ? unconfirmed.slice(0, 8).map(({ post, a }) => `<div class="gap-card"><div class="gap-status">✦</div><div style="flex:1"><strong>${esc(a.name)}</strong><p>For: ${esc(post.title)} · ${esc(post.platform)}</p>${a.possibleMatches?.length ? `<p><b>Possible file match (unverified):</b> ${a.possibleMatches.map(esc).join(', ')}</p>` : '<p>No filename/tag candidate found</p>'}</div><button class="btn small outline" onclick="openPost(${Number(post.id)})">Review ↗</button></div>`).join('') : '<p class="small muted">No automatic suggestions awaiting review.</p>'}</section>`;
  return base.replace('<div class="grid-main">', extra + cards + '<div class="grid-main">')
};

// An IndexedDB file store allows a single-browser demo to retain selected files across refreshes.
// It does not synchronise files between Charlotte and Naomi or provide private cloud storage.
function v10OpenDB() { return new Promise((resolve, reject) => { if (!window.indexedDB) return reject(new Error('IndexedDB unavailable')); let req = indexedDB.open('charlotte_ai_local_demo_v10', 1); req.onupgradeneeded = () => req.result.createObjectStore('media'); req.onsuccess = () => resolve(req.result); req.onerror = () => reject(req.error) }) }
async function v10StoreBlob(key, blob) { try { const db = await v10OpenDB(); await new Promise((resolve, reject) => { const tx = db.transaction('media', 'readwrite'); tx.objectStore('media').put(blob, String(key)); tx.oncomplete = resolve; tx.onerror = () => reject(tx.error) }); db.close() } catch (e) { console.warn('Local file persistence failed', e); toast('Media preview is session-only in this browser') } }
async function v10RestoreBlobs() { try { const db = await v10OpenDB(); const data = await new Promise((resolve, reject) => { const tx = db.transaction('media', 'readonly'); const store = tx.objectStore('media'); const k = store.getAllKeys(), v = store.getAll(); tx.oncomplete = () => resolve([k.result, v.result]); tx.onerror = () => reject(tx.error) }); db.close(); let found = 0; data[0].forEach((key, i) => { const blob = data[1][i]; if (String(key).startsWith('voice:')) audioFiles[String(key).slice(6)] = URL.createObjectURL(blob); else if (state.media.some(m => String(m.id) === String(key))) { mediaFiles[key] = URL.createObjectURL(blob); found++ } }); if (found && (!activePostId || role === 'charlotte')) render(); } catch (e) { console.warn('Local file restore unavailable', e) } }
function v10RegisterFile(file, tag, storyId, postId) { let id = Date.now() + Math.random(); let type = file.type.startsWith('image/') ? 'image' : file.type.startsWith('video/') ? 'video' : 'audio'; state.media.unshift({ id, name: file.name, type, emoji: type === 'image' ? '▧' : type === 'video' ? '▶' : '◉', tag, storyId, postId, sample: false }); mediaFiles[id] = URL.createObjectURL(file); v10StoreBlob(id, file); caRememberThumb(id, file); return id }

function v10AttachmentList() { const slot = document.getElementById('v10StoryFileList'); if (!slot) return; slot.innerHTML = v10StoryFiles.length ? `<div class="v10-attached-grid">${v10StoryFiles.map((it, i) => `<div class="v10-attached-item">${it.file.type.startsWith('image/') ? `<img src="${esc(it.url)}" alt="${esc(it.file.name)}">` : '<div style="font-size:22px;width:44px;text-align:center">▶</div>'}<div><b>${esc(it.file.name)}</b><small>${(it.file.size / 1048576).toFixed(1)} MB</small></div><button type="button" aria-label="Remove ${esc(it.file.name)}" onclick="v10RemoveStoryFile(${i})">×</button></div>`).join('')}</div>` : '<div class="v10-upload-note" style="margin-top:8px">No supporting photos or videos attached yet. Optional.</div>' }
function v10AddStoryFiles(files) { for (const f of Array.from(files || [])) { if (!(f.type.startsWith('image/') || f.type.startsWith('video/'))) continue; v10StoryFiles.push({ file: f, url: URL.createObjectURL(f) }) } v10AttachmentList() }
function v10ReadStoryFiles(e) { v10AddStoryFiles(e.target.files); e.target.value = '' }
function v10RemoveStoryFile(i) { const x = v10StoryFiles.splice(i, 1)[0]; if (x) URL.revokeObjectURL(x.url); v10AttachmentList() }
function v10DropStory(e) { e.preventDefault(); e.stopPropagation(); e.currentTarget.classList.remove('drag'); v10AddStoryFiles(e.dataTransfer.files) }
viewRecord = function () { const base = v10PreviousRecord(); const block = `<section class="v10-story-media"><div class="v10-story-media-head"><div><h3>Photos and videos for this story</h3><p>Optional: add the images or clips you already have. Charlotte can request more later.</p></div><span class="pill outline">Linked to this voice note</span></div><input hidden id="v10StoryFileInput" type="file" accept="image/*,video/*" multiple onchange="v10ReadStoryFiles(event)"><div role="button" tabindex="0" class="v10-story-drop" onclick="document.getElementById('v10StoryFileInput').click()" onkeydown="if(event.key==='Enter')this.click()" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="v10DropStory(event)">＋ Upload or drag photos and videos with your voice note</div><div id="v10StoryFileList"></div></section>`; return base.replace('<div class="field spaced"><label>Theme</label>', block + '<div class="field spaced"><label>Theme</label>') };
const v10BeforeBind = bindCurrent;
bindCurrent = function () { v10BeforeBind(); if (page === 'record') v10AttachmentList() };
saveStory = function () { let title = document.getElementById('storyTitle')?.value.trim() || '', text = document.getElementById('storyTranscript')?.value.trim() || ''; if (!title && !text) return v10PreviousSaveStory(); if (!title && !text && audioChunks.length) { const input = document.getElementById('storyTitle'); if (input) input.value = 'Voice note · ' + new Date().toLocaleDateString('en-AU'); } const before = state.stories.length; const pending = [...v10StoryFiles]; const voice = audioChunks.length ? new Blob(audioChunks, { type: audioRecorder?.mimeType || 'audio/webm' }) : null; v10PreviousSaveStory(); if (state.stories.length <= before) return; const s = state.stories[0]; s.mediaIds = []; for (const item of pending) { s.mediaIds.push(v10RegisterFile(item.file, 'Supporting media for story ' + s.title, s.id, null)); URL.revokeObjectURL(item.url) } if (voice) v10StoreBlob('voice:' + s.id, voice); v10StoryFiles = []; s.assetSuggestions = v10SuggestionsFor([s.title, s.text, s.theme].join(' '), ''); save(); render(); toast(`Story saved with ${s.mediaIds.length} attached media file${s.mediaIds.length === 1 ? '' : 's'} (local demo).`) };
function v10MakeDraftFromStory() { const id = document.getElementById('v10LinkedStory')?.value, format = document.getElementById('v10NewFormat')?.value || 'Reel', platform = document.getElementById('v10NewPlatform')?.value || 'Instagram', story = state.stories.find(x => String(x.id) === String(id)); if (!story) { toast('Select a story first'); return } if (platform === 'LinkedIn' && format === 'Story') { toast('LinkedIn Stories are unavailable. Choose Photo, Carousel or Video/Reel.'); return } const nextId = Math.max(100, ...state.posts.map(x => Number(x.id) || 0)) + 1, date = caLocalISO(caPlusDays(new Date(), 7)); const p = { id: nextId, title: 'From voice note · ' + story.title, platform, format, theme: story.theme || 'Founder story', status: 'draft', date, emoji: '◉', visual: 'business', caption: story.text || '', comments: [], assets: [], storyId: story.id }; state.posts.unshift(p); v10ScanOne(p); save(); openPost(p.id); toast('Draft created from story source. Refine the caption and confirm media before approval.') }
viewStories = function () { const html = v10PreviousStories(); const linked = state.stories.filter(s => s.mediaIds?.length || s.assetSuggestions?.length); const addition = `<section class="card cardpad spaced"><div class="card-header"><h3>Story-linked media & suggested needs</h3><span class="pill outline">${linked.length} stories indexed</span></div><p class="v10-upload-note">These are rule-generated prompts based on the story text. Uploaded photos and videos appear under that story; visual content has not been analysed by AI.</p>${linked.map(s => `<div class="gap-card"><div class="gap-status found">◉</div><div style="flex:1"><strong>${esc(s.title)}</strong><div class="v10-story-links">${(s.mediaIds || []).map(id => { let m = state.media.find(x => String(x.id) === String(id)); return m ? `<span>▧ ${esc(m.name)}</span>` : '' }).join('')}${(s.assetSuggestions || []).map(name => `<span>Suggested: ${esc(name)}</span>`).join('')}</div></div></div>`).join('')}</section>`; const create = `<section class="card cardpad spaced"><div class="card-header"><h3>Create a draft from Naomi’s story</h3><span class="pill outline">Charlotte workflow</span></div><div class="v10-data-note">Keeps the original story transcript as source text. This demonstration does not invent a new caption or run a remote AI model.</div><div class="editor-grid"><div class="field"><label>Choose story</label><select id="v10LinkedStory">${state.stories.map(s => `<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></div><div class="field"><label>Platform</label><select id="v10NewPlatform"><option>Instagram</option><option>Facebook</option><option>LinkedIn</option></select></div><div class="field"><label>Content format</label><select id="v10NewFormat"><option>Reel</option><option>Carousel</option><option>Photo</option><option>Story</option></select></div></div><button class="btn primary spaced" onclick="v10MakeDraftFromStory()">＋ Create linked draft</button></section>`; return html + create + addition };

function v10Format(p) { const f = String(p.format || '').toLowerCase(); return /story/.test(f) ? 'Story' : /reel|video/.test(f) ? 'Reel' : /carousel/.test(f) ? 'Carousel' : 'Feed' }
function v10AvailableModes(p) { return p.platform === 'LinkedIn' ? ['Feed', 'Video'] : ['Feed', 'Reel', 'Story'] }
function v10SetMode(mode) { v10PreviewMode = mode; renderDrawer() }
function v10MediaVisual(p, mode) { const m = state.media.find(x => String(x.id) === String(p.mediaId)), url = m && mediaFiles[m.id]; const nativeVideo = (m?.type === 'video' && url); const vis = nativeVideo ? `<video controls playsinline preload="metadata" src="${esc(url)}" style="height:100%;width:100%;object-fit:cover"></video>` : caThumb(p, { flag: false }); return `<div class="v10-media-frame ${mode === 'Reel' || mode === 'Video' ? 'reel' : mode === 'Story' ? 'story' : 'feed'}">${vis}${mode === 'Story' ? `<div class="v10-story-head"><div class="v10-story-progress"><i></i><i></i><i></i></div><b>naomi · just now</b>　⋯</div>` : ''}${(mode === 'Reel' || mode === 'Video') ? `<div class="v10-reel-copy"><b>naomi</b>　${esc((p.caption || '').slice(0, 145))}${p.caption?.length > 145 ? '…' : ''}</div><div class="v10-reel-actions">♡<br>☏<br>➤</div>` : ''}</div>` }
function v10PlatformPreview(p) {
  let modes = v10AvailableModes(p); let def = v10Format(p); if (p.platform === 'LinkedIn') def = def === 'Reel' ? 'Video' : 'Feed'; let mode = modes.includes(v10PreviewMode) ? v10PreviewMode : def; const mobileStyle = (mode === 'Story' || mode === 'Reel' || mode === 'Video'); let modeTabs = `<div class="v10-tab-switch">${modes.map(m => `<button class="${mode === m ? 'active' : ''}" onclick="v10SetMode('${m}')">${m === 'Feed' ? 'Feed' : m === 'Video' ? 'Video' : m}</button>`).join('')}</div>`;
  let image = v10MediaVisual(p, mode), caption = esc(p.caption || 'No caption yet.');
  let body = '';
  if (p.platform === 'Instagram') body = mode === 'Story' ? image : mobileStyle ? image : `<div class="v10-feed-head"><div class="v10-avatar">N</div><div class="v10-feed-name"><b>naomi.demo</b><small>Sample profile · Instagram</small></div><span class="v10-feed-more">⋯</span></div>${image}${v10Format(p) === 'Carousel' ? '<div style="text-align:center;color:#999;font-size:10px;padding:5px">● ○ ○　Carousel preview</div>' : ''}<div class="v10-feed-actions">♡　☏　➤ <span class="v10-push">▢</span></div><div class="v10-feed-count">Preview • reactions not simulated</div><div class="v10-feed-caption"><b>naomi.demo</b> ${caption}</div>`;
  else if (p.platform === 'Facebook') body = mode === 'Story' ? image : mobileStyle ? image : `<div class="v10-feed-head"><div class="v10-avatar">N</div><div class="v10-feed-name"><b>Naomi · Demo</b><small>Just now · Public 🌐</small></div><span class="v10-feed-more">⋯</span></div><div class="v10-feed-caption">${caption}</div>${image}<div class="v10-feed-actions">♡ Like <span>☏ Comment</span><span>➤ Share</span></div>`;
  else body = `<div class="v10-feed-head"><div class="v10-avatar">N</div><div class="v10-feed-name"><b>Naomi · Founder</b><small>Sample LinkedIn profile · Just now</small></div><span class="v10-feed-more">⋯</span></div><div class="v10-feed-caption">${caption}</div>${image}<div class="v10-feed-actions">♡ Like <span>☏ Comment</span><span>⇄ Repost</span><span>➤ Send</span></div>`;
  return `<div class="v10-review-drawer-head"><div><div class="v10-platform-label">${esc(p.platform)} preview</div><h3>${esc(p.title)}</h3></div>${statusBadge(p.status)}</div><p class="v10-review-intro">Review the actual caption and media placement in a familiar social format. Tap a format to compare previews; this does not change the scheduled content type.</p>${modeTabs}<div class="v10-app-preview ${p.platform === 'Facebook' ? 'v10-fb' : p.platform === 'LinkedIn' ? 'v10-linkedin' : ''}">${body}</div><p class="v10-preview-footnote">Platform-style approximation, not an official live ${esc(p.platform)} rendering. Photo/cover may be illustrative.</p>`
}
function v10ReviewCard(p) { return `<button class="v10-review-card" onclick="openPost(${Number(p.id)})">${caThumb(p, { flag: true, clean: true })}<div class="v10-review-meta"><b>${esc(p.title)}</b><small>${esc(p.platform)} · ${esc(p.format)} · ${esc(p.date)}</small><div class="v10-review-state">${statusBadge(p.status)}<span>Open ↗</span></div></div></button>` }
viewReview = function () { const queued = state.posts.filter(p => ['pending', 'changes'].includes(p.status)), done = state.posts.filter(p => ['approved', 'scheduled'].includes(p.status)); return `${head('Review your posts', 'See each post the way your followers would see it. Approve or request changes with one tap.')}<div class="v10-data-note"><b>Review first, edit second.</b> Posts open in a platform-style preview. Caption fields unlock only after you choose Request Changes. Naomi can suggest new media without changing the selected cover.</div><section class="card cardpad"><div class="card-header"><h3>Needs your review</h3><span class="pill pending">${queued.length} posts</span></div><div class="v10-review-grid">${queued.length ? queued.map(v10ReviewCard).join('') : '<p class="small muted">All caught up.</p>'}</div></section><section class="card cardpad spaced"><div class="card-header"><h3>Approved or scheduled</h3><span class="pill approved">${done.length} posts</span></div><div class="v10-review-grid">${done.map(v10ReviewCard).join('')}</div></section>` };

function v10BeginChanges() { const p = state.posts.find(p => p.id === activePostId); if (!p) return; v10EditingPost = p.id; v10SuggestOpen = false; if (p.status !== 'changes') changeStatus('changes'); else renderDrawer() }
function v10FinishChanges() { const p = state.posts.find(p => p.id === activePostId); if (!p) return; const text = document.getElementById('v10ChangeComment')?.value.trim(); if (text) { p.comments ??= []; p.comments.push({ who: 'Naomi', text, date: new Date().toLocaleDateString('en-AU') }) } p.status = 'changes'; p.changeHistory ??= []; p.changeHistory.push({ at: new Date().toISOString(), by: 'naomi', event: 'feedback_submitted' }); save(); v10EditingPost = null; renderDrawer(); toast('Feedback saved for Charlotte in this browser demo') }
function v10ExitEdit() { v10EditingPost = null; renderDrawer() }
function v10Approve() { const p = state.posts.find(x => x.id === activePostId); if (!p) return; v10EditingPost = null; changeStatus('approved') }
function v10SuggestionToggle() { v10SuggestOpen = !v10SuggestOpen; renderDrawer() }
function v10SuggestionInput(e) { v10SuggestionFiles = Array.from(e.target.files || []).filter(f => f.type.startsWith('image/') || f.type.startsWith('video/')); const msg = document.getElementById('v10SuggestionFiles'); if (msg) msg.textContent = v10SuggestionFiles.length ? v10SuggestionFiles.map(f => f.name).join(', ') : 'No file chosen' }
function v10SubmitSuggestion() { const p = state.posts.find(x => x.id === activePostId); if (!p) return; const type = document.getElementById('v10MediaType')?.value || 'Photo', note = document.getElementById('v10MediaNote')?.value.trim() || ''; if (!note && !v10SuggestionFiles.length) { toast('Describe the suggested media or attach a file'); return } let ids = []; for (const f of v10SuggestionFiles) { ids.push(v10RegisterFile(f, 'Naomi suggestion · ' + p.title, null, p.id)) } p.mediaSuggestions ??= []; p.mediaSuggestions.push({ id: 'suggest_' + Date.now(), type, note: note || 'Please consider the attached media', mediaIds: ids, from: 'Naomi', date: new Date().toISOString(), status: 'For Charlotte to review' }); p.status = 'changes'; p.changeHistory ??= []; p.changeHistory.push({ at: new Date().toISOString(), by: 'naomi', event: 'media_suggested' }); v10SuggestionFiles = []; v10SuggestOpen = false; save(); renderDrawer(); toast('Media suggestion sent to Charlotte’s review queue — original visual unchanged') }
function v10SuggestionsList(p) { return (p.mediaSuggestions || []).length ? `<div class="v10-suggestions-list">${p.mediaSuggestions.slice().reverse().map(s => `<div class="v10-suggestion-card"><div><b>${esc(s.type)} suggestion</b><div>${esc(s.note)}</div>${(s.mediaIds || []).map(id => { let m = state.media.find(x => String(x.id) === String(id)); return m ? `<small>Attachment: ${esc(m.name)}</small>` : '' }).join('<br>')}</div><span class="status">Pending Charlotte</span></div>`).join('')}</div>` : '' }
