function v12Labels(m) { return m.displayName || m.name || 'Untitled asset' }
function v12Collections() { return ['All collections', ...new Set(state.media.map(m => m.collection || 'Unsorted').filter(Boolean))].sort((a, b) => a === 'All collections' ? -1 : b === 'All collections' ? 1 : a.localeCompare(b)) }
function v12Pic(m) { const src = m.thumbData || mediaFiles[m.id]; if (src) return `<img src="${esc(src)}" alt="${esc(v12Labels(m))}" loading="lazy">`; return `<span aria-hidden="true">${esc(m.emoji || (m.type === 'video' ? '▶' : m.type === 'audio' ? '◉' : '▧'))}</span>` }
function v12Index(m) { return [m.name, m.displayName, m.tag, (m.tags || []).join(' '), m.collection, m.notes, (m.storyId || ''), ...v12LinkedPosts(m).map(p => p.title)].join(' ').toLowerCase() }
function v12FilteredMedia() { return state.media.filter(m => { const query = v12Search.trim().toLowerCase(); const inText = !query || query.split(/\s+/).every(term => v12Index(m).includes(term)); const inCollection = v12Collection === 'All collections' || (m.collection || 'Unsorted') === v12Collection; const inType = v12Type === 'All media' || m.type === v12Type; const linked = v12LinkedPosts(m).length > 0; return inText && inCollection && inType && (v12LinkFilter === 'All assets' || (v12LinkFilter === 'Linked to drafts' ? linked : !linked)) }) }
function v12Tile(m) { const linked = v12LinkedPosts(m), checked = v12Selected.has(String(m.id)); return `<div class="v12-tile" role="button" tabindex="0" aria-label="Organise ${esc(v12Labels(m))}" onclick="v12OpenAsset(${jsq(m.id)})" onkeydown="if(event.key==='Enter'){event.preventDefault();v12OpenAsset(${jsq(m.id)})}"><input class="v12-check" type="checkbox" aria-label="Select ${esc(v12Labels(m))}" ${checked ? 'checked' : ''} onclick="event.stopPropagation()" onchange="v12ToggleSelected(${jsq(m.id)},this.checked)"><div class="v12-tile-media">${v12Pic(m)}<span class="v12-media-indicator">${esc(m.type || 'media')}</span></div><div class="v12-tile-body"><strong>${esc(v12Labels(m))}</strong><div class="desc">${esc(m.collection || 'Unsorted')}${m.sample ? ' · Sample asset' : ''}</div><div class="v12-tags">${v12AllTags(m).slice(0, 2).map(tag => `<span class="v12-tag">${esc(tag)}</span>`).join('')}${linked.length ? `<span class="v12-tag v12-linked-tag">${linked.length} draft${linked.length === 1 ? '' : 's'}</span>` : ''}</div></div></div>` }
function v12Gallery() { const list = v12FilteredMedia(); return list.length ? list.map(v12Tile).join('') : `<div class="v12-empty">No assets match these filters. Try another collection, tag or search term.</div>` }
function v12LibraryHTML() { const count = state.media.length, linked = state.media.filter(m => v12LinkedPosts(m).length).length; return `<div class="v12-lib-header"><div><h3>Media Organizer</h3><p>Give each upload a useful label, group it into a collection, add searchable tags, and link it to one or more drafts.</p></div><div class="v12-lib-action"><button class="primary" type="button" onclick="document.getElementById('filePicker').click()">＋ Upload media</button><button type="button" onclick="v12BulkOpen()" id="v12BulkButton">Organise selected (${v12Selected.size})</button></div></div><div class="v12-search-tools"><div class="v12-field-mini"><label for="v12Search">Search labels, tags, drafts</label><input id="v12Search" placeholder="e.g. Bondi, founder, athletics" value="${esc(v12Search)}" oninput="v12Search=this.value;v12UpdateGallery()"></div><div class="v12-field-mini"><label for="v12Collection">Collection</label><select id="v12Collection" onchange="v12Collection=this.value;v12MountMediaLibrary()">${v12Collections().map(c => `<option ${v12Collection === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></div><div class="v12-field-mini"><label for="v12Type">Media format</label><select id="v12Type" onchange="v12Type=this.value;v12MountMediaLibrary()">${[['All media', 'All media'], ['image', 'Photos'], ['video', 'Videos'], ['audio', 'Audio']].map(([v, n]) => `<option value="${v}" ${v12Type === v ? 'selected' : ''}>${n}</option>`).join('')}</select></div><div class="v12-field-mini"><label for="v12Link">Draft assignment</label><select id="v12Link" onchange="v12LinkFilter=this.value;v12MountMediaLibrary()">${['All assets', 'Linked to drafts', 'Not linked yet'].map(x => `<option ${v12LinkFilter === x ? 'selected' : ''}>${x}</option>`).join('')}</select></div></div><div class="v12-resultline"><span id="v12Count">${count} media files · ${linked} linked to drafts</span><span>Click a thumbnail to organise or attach it</span></div><div class="v12-results" id="v12Results">${v12Gallery()}</div><div class="v12-helper">Labels and connections are saved in this browser. Matching suggestions use your filenames, tags and notes—not image recognition. No files are sent to Naomi or published by this action.</div>` }
function v12MountMediaLibrary() { if (role !== 'charlotte' || page !== 'assets') return; let h = [...document.querySelectorAll('.card-header h3')].find(el => el.textContent.trim() === 'Media library'); const panel = h?.closest('.card') || document.querySelector('.v12-media-panel'); if (!panel) return; panel.classList.add('v12-media-panel'); panel.innerHTML = v12LibraryHTML(); const topBtn = document.querySelector('.pagehead .btn.primary'); if (topBtn) { topBtn.textContent = '＋ Upload media'; topBtn.onclick = () => document.getElementById('filePicker').click() } }
function v12UpdateGallery() { const target = document.getElementById('v12Results'); if (target) target.innerHTML = v12Gallery(); const c = document.getElementById('v12Count'); if (c) c.textContent = `${v12FilteredMedia().length} shown of ${state.media.length} files · ${state.media.filter(m => v12LinkedPosts(m).length).length} linked to drafts` }
function v12ToggleSelected(id, checked) { if (checked) v12Selected.add(String(id)); else v12Selected.delete(String(id)); const btn = document.getElementById('v12BulkButton'); if (btn) btn.textContent = `Organise selected (${v12Selected.size})` }
function v12CloseDialog() { document.getElementById('v12AssetDialog')?.remove() }
function v12Dialog(content) { v12CloseDialog(); const el = document.createElement('div'); el.className = 'v12-modal-bg'; el.id = 'v12AssetDialog'; el.setAttribute('role', 'presentation'); el.innerHTML = `<section class="v12-dialog" role="dialog" aria-modal="true" aria-label="Media organiser">${content}</section>`; el.addEventListener('click', e => { if (e.target === el) v12CloseDialog() }); document.body.appendChild(el); el.querySelector('.v12-dialog button')?.focus() }
function v12Recommended(m) { let tags = v12AllTags(m).map(x => x.toLowerCase()), query = (m.displayName + ' ' + (m.collection || '') + ' ' + (m.notes || '')).toLowerCase().split(/\W+/).filter(x => x.length > 3); const stop = new Set(['photo', 'video', 'media', 'image', 'new', 'upload', 'draft', 'with', 'about', 'founder', 'story']); return state.posts.map(p => { const theme = (p.theme || '').toLowerCase(); let score = tags.some(t => theme.includes(t) || t.includes(theme)) ? 6 : 0; const test = (p.title + ' ' + p.caption).toLowerCase(); score += query.filter(x => !stop.has(x) && test.includes(x)).length; return { p, score } }).filter(x => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 4) }
function v12DraftRows(m) { const rows = v12LinkedPosts(m), rec = v12Recommended(m).filter(({ p }) => !rows.some(x => String(x.id) === String(p.id))); return `<div class="v12-dialog-section"><h3>Linked drafts (${rows.length})</h3><p>This is a reference to the asset, not proof that it fulfils Charlotte's creative request.</p>${rows.length ? rows.map(p => `<div class="v12-suggest"><div><strong>${esc(p.title)}</strong><small>${esc(p.platform)} · ${esc(p.format)}${String(p.mediaId) === String(m.id) ? ' · Main visual' : ''}</small></div><button onclick="v12UnlinkMedia(${jsq(m.id)},${jsq(p.id)})">Unlink</button></div>`).join('') : '<div class="v12-empty">No drafts linked yet.</div>'}<div class="v12-form-grid" style="margin-top:12px"><div class="field"><label>Choose a draft</label><select id="v12DraftSelect"><option value="">Select a draft…</option>${state.posts.map(p => `<option value="${esc(p.id)}">${esc(p.title)} (${esc(p.platform)})</option>`).join('')}</select></div><div class="field"><label>Attach to draft</label><div class="btn-row"><button class="btn outline small" onclick="v12LinkFromSelect(${jsq(m.id)},'reference')">Link as reference</button><button class="btn primary small" onclick="v12LinkFromSelect(${jsq(m.id)},'cover')" ${m.type === 'audio' ? 'disabled' : ''}>Use as main visual</button></div></div></div>${rec.length ? `<div style="margin-top:14px"><b class="small">Suggested by labels and tags</b><p style="font-size:10px;color:#89939a;margin-top:5px">These are possible matches to review, not verified AI visual matches.</p>${rec.map(({ p }) => `<div class="v12-suggest"><div><strong>${esc(p.title)}</strong><small>${esc(p.theme)} · ${esc(p.platform)}</small></div><button onclick="v12LinkMedia(${jsq(m.id)},${jsq(p.id)},'reference')">Link</button></div>`).join('')}</div>` : ''}</div>` }
function v12OpenAsset(id) { const m = v12GetMedia(id); if (!m) return; const html = `<div class="v12-dialog-head"><div><span class="eyebrow">CHARLOTTE · MEDIA ORGANIZER</span><h2>Label and match this media</h2><p>Organise once, reuse across drafts. Naomi's uploaded original is not altered.</p></div><button class="btn outline small" onclick="v12CloseDialog()">✕ Close</button></div><div class="v12-dialog-layout"><div><div class="v12-modal-preview">${v12Pic(m)}</div><p class="v12-dialog-file"><b>Original filename:</b> ${esc(m.name)}<br><b>Type:</b> ${esc(m.type)}${m.sample ? ' · Sample placeholder' : ''}${m.storyId ? '<br><b>Attached to story:</b> ' + esc((state.stories.find(s => String(s.id) === String(m.storyId)) || {}).title || String(m.storyId)) : ''}</p></div><div><div class="v12-form-grid"><div class="field v12-formgrid-full"><label>Display label *</label><input id="v12AssetLabel" maxlength="120" value="${esc(v12Labels(m))}" placeholder="e.g. Naomi speaking on stage — IWD"></div><div class="field"><label>Collection / folder</label><input id="v12AssetCollection" maxlength="75" value="${esc(m.collection || 'Unsorted')}" list="v12CollectionsList" placeholder="e.g. Founder journey"><datalist id="v12CollectionsList">${v12Collections().filter(c => c !== 'All collections').map(c => `<option value="${esc(c)}">`).join('')}</datalist></div><div class="field"><label>Tags (comma separated)</label><input id="v12AssetTags" value="${esc((m.tags || []).join(', '))}" placeholder="ADHD, candid, behind the scenes"></div><div class="field v12-formgrid-full"><label>Notes / context</label><textarea id="v12AssetNotes" rows="3" placeholder="Who, where, when, what happened, which story does it support?">${esc(m.notes || '')}</textarea></div></div><button class="btn primary spaced" onclick="v12SaveAsset(${jsq(m.id)})">✓ Save media labels</button></div></div><div id="v12DraftLinkArea">${v12DraftRows(m)}</div>`; v12Dialog(html) }
function v12SaveAsset(id) { const m = v12GetMedia(id); if (!m) return; const name = document.getElementById('v12AssetLabel')?.value.trim(); if (!name) { toast('Add a label for the media'); document.getElementById('v12AssetLabel')?.focus(); return } m.displayName = name; m.collection = document.getElementById('v12AssetCollection')?.value.trim() || 'Unsorted'; m.tags = [...new Set((document.getElementById('v12AssetTags')?.value || '').split(',').map(x => x.trim()).filter(Boolean))].slice(0, 20); m.notes = (document.getElementById('v12AssetNotes')?.value || '').trim(); m.editedBy = 'Charlotte'; m.editedAt = new Date().toISOString(); save(); v12MountMediaLibrary(); v12OpenAsset(id); toast('Media label, collection and tags saved') }
function v12LinkFromSelect(id, mode) { const postId = document.getElementById('v12DraftSelect')?.value; if (!postId) { toast('Select a draft first'); return } v12LinkMedia(id, postId, mode) }
function v12LinkMedia(id, postId, mode = 'reference') { const m = v12GetMedia(id), p = state.posts.find(x => String(x.id) === String(postId)); if (!m || !p) return; if (mode === 'cover' && m.type === 'audio') { toast('Choose a photo or video as the main visual'); return } p.mediaReferences ??= []; if (!p.mediaReferences.some(x => String(x) === String(id))) p.mediaReferences.push(m.id); m.linkedPostIds ??= []; if (!m.linkedPostIds.some(x => String(x) === String(postId))) m.linkedPostIds.push(p.id); if (mode === 'cover' && String(p.mediaId) !== String(m.id)) { p.mediaId = m.id; p.revision = (p.revision || 1) + 1; if (['approved', 'scheduled'].includes(p.status)) p.status = 'pending' } save(); if (page === 'assets') v12MountMediaLibrary(); if (document.getElementById('v12AssetDialog')) v12OpenAsset(id); if (activePostId && String(activePostId) === String(postId) && document.getElementById('drawerWrap')?.classList.contains('open')) { renderDrawer() } toast(mode === 'cover' ? 'Main visual updated; approval reopens if necessary' : 'Asset linked to draft as a reference — request not auto-fulfilled') }
function v12UnlinkMedia(id, postId) { const m = v12GetMedia(id), p = state.posts.find(x => String(x.id) === String(postId)); if (!m || !p) return; const cover = String(p.mediaId) === String(m.id); if (cover && !confirm('This is the main visual. Unlinking will remove it from the draft and may require re-approval. Continue?')) return; m.linkedPostIds = (m.linkedPostIds || []).filter(x => String(x) !== String(postId)); p.mediaReferences = (p.mediaReferences || []).filter(x => String(x) !== String(id)); if (cover) { p.mediaId = null; p.revision = (p.revision || 1) + 1; if (['approved', 'scheduled'].includes(p.status)) p.status = 'pending' } save(); if (page === 'assets') v12MountMediaLibrary(); v12OpenAsset(id); if (activePostId && String(activePostId) === String(postId)) renderDrawer(); toast('Asset unlinked from the draft') }
function v12BulkOpen() { const ids = Array.from(v12Selected).filter(id => v12GetMedia(id)); if (!ids.length) { toast('Select at least one media file first'); return } v12Dialog(`<div class="v12-dialog-head"><div><div class="eyebrow">BULK ORGANISE</div><h2>Organise ${ids.length} selected media files</h2><p>Apply one collection or add shared tags to these assets.</p></div><button class="btn outline small" onclick="v12CloseDialog()">✕ Close</button></div><div class="v12-form-grid"><div class="field"><label>Move to collection (optional)</label><input id="v12BulkCollection" list="v12CollectionsList" placeholder="e.g. Race footage"><datalist id="v12CollectionsList">${v12Collections().filter(c => c !== 'All collections').map(c => `<option value="${esc(c)}">`).join('')}</datalist></div><div class="field"><label>Add these tags (optional)</label><input id="v12BulkTags" placeholder="HYROX, training, finish line"></div></div><div class="v12-dialog-bottom"><button class="btn outline" onclick="v12CloseDialog()">Cancel</button><button class="btn primary" onclick="v12BulkSave()">Apply to ${ids.length} files</button></div>`) }
function v12BulkSave() { const ids = [...v12Selected], collection = document.getElementById('v12BulkCollection')?.value.trim(), tags = (document.getElementById('v12BulkTags')?.value || '').split(',').map(s => s.trim()).filter(Boolean); if (!collection && !tags.length) { toast('Enter a collection or tags to apply'); return } ids.forEach(id => { const m = v12GetMedia(id); if (!m) return; if (collection) m.collection = collection; m.tags = [...new Set([...(m.tags || []), ...tags])].slice(0, 20); m.editedBy = 'Charlotte' }); v12Selected.clear(); save(); v12CloseDialog(); v12MountMediaLibrary(); toast(`Organised ${ids.length} media files`) }
function v12FindFromGap(label) { const terms = label.toLowerCase().split(/\W+/).filter(x => x.length > 3 && !['photo', 'video', 'footage', 'image', 'short', 'clips', 'with'].includes(x)); v12Search = terms.slice(0, 2).join(' '); v12Collection = 'All collections'; v12Type = 'All media'; v12LinkFilter = 'All assets'; v12MountMediaLibrary(); document.getElementById('v12Search')?.focus(); document.querySelector('.v12-media-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function v12ShowInGap() { if (role !== 'charlotte' || page !== 'assets') return; const gapCard = [...document.querySelectorAll('.card-header h3')].find(x => x.textContent.includes('Asset requests'))?.closest('.card'); if (!gapCard) return; gapCard.querySelectorAll('.gap-card').forEach(el => { if (el.querySelector('.v12-find-link')) return; const name = el.querySelector('strong')?.textContent || ''; const button = document.createElement('button'); button.type = 'button'; button.className = 'text-link v12-find-link'; button.textContent = 'Find matching media ↗'; button.style.marginLeft = '10px'; button.onclick = () => v12FindFromGap(name); el.querySelector('div:nth-child(2)')?.appendChild(button) }) }
// Keep the existing upload workflow, but make the post's media picker searchable.
showMediaPicker = function () { const host = document.getElementById('pickerPanel'), post = state.posts.find(p => String(p.id) === String(activePostId)); if (!host || !post) return; const relevant = state.media.filter(m => m.type === 'image' || m.type === 'video').filter(m => { if (v12PickerCollection !== 'All collections' && (m.collection || 'Unsorted') !== v12PickerCollection) return false; const q = v12PickerSearch.toLowerCase().trim(); return !q || q.split(/\s+/).every(t => v12Index(m).includes(t)) }).sort((a, b) => { const a1 = v12Recommended(a).some(x => String(x.p.id) === String(post.id)) ? 1 : 0, b1 = v12Recommended(b).some(x => String(x.p.id) === String(post.id)) ? 1 : 0; return b1 - a1 }); host.innerHTML = `<div class="v12-inline-picker"><div class="flex-between"><div><strong>Find media for “${esc(post.title)}”</strong><p class="v12-helper">Search tags and collections. Link a reference or select a main visual.</p></div><button class="btn small outline" onclick="document.getElementById('pickerPanel').innerHTML=''">Close</button></div><div class="v12-search-tools"><div class="v12-field-mini"><label>Search media</label><input id="v12PickerSearch" value="${esc(v12PickerSearch)}" oninput="v12PickerSearch=this.value;v12RefreshPickerResults()" placeholder="Search filename, tags, description"></div><div class="v12-field-mini"><label>Collection</label><select onchange="v12PickerCollection=this.value;showMediaPicker()">${v12Collections().map(c => `<option ${v12PickerCollection === c ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></div></div><div id="v12PickerResults" class="v12-inline-results">${v12PickerRows(relevant, post)}</div></div>` }
function v12PickerRows(rows, p) { return rows.length ? rows.slice(0, 30).map(m => `<div class="v12-picker-tile"><div class="v12-mini-img">${v12Pic(m)}</div><div class="v12-picker-meta"><b>${esc(v12Labels(m))}</b><small>${esc(m.collection || 'Unsorted')} · ${esc(v12AllTags(m).slice(0, 2).join(', ') || m.type)}</small></div><div class="v12-picker-actions"><button onclick="v12LinkMedia(${jsq(m.id)},${jsq(p.id)},'reference')">Link</button><button class="primary" onclick="v12LinkMedia(${jsq(m.id)},${jsq(p.id)},'cover')">Use visual</button></div></div>`).join('') : '<div class="v12-empty">No matching media. Try different keywords or upload a new file.</div>' }
function v12RefreshPickerResults() { const host = document.getElementById('v12PickerResults'), p = state.posts.find(x => String(x.id) === String(activePostId)); if (!host || !p) return; const rows = state.media.filter(m => ['image', 'video'].includes(m.type)).filter(m => (v12PickerCollection === 'All collections' || (m.collection || 'Unsorted') === v12PickerCollection) && (!v12PickerSearch.trim() || v12PickerSearch.toLowerCase().trim().split(/\s+/).every(t => v12Index(m).includes(t)))); host.innerHTML = v12PickerRows(rows, p) }
const v12PreviousMatch = v10MatchName; v10MatchName = function (asset, media) { if (v12PreviousMatch(asset, media)) return true; const words = String(asset).toLowerCase().split(/\W+/).filter(t => t.length >= 5 && !['photos', 'videos', 'photo', 'video', 'footage', 'image', 'needed'].includes(t)); return words.some(t => v12Index(media).includes(t)) };
const v12PreviousBind = bindCurrent;
bindCurrent = function () { v12PreviousBind(); if (role === 'charlotte' && page === 'assets') { v12MountMediaLibrary(); v12ShowInGap() } };
document.addEventListener('keydown', e => { if (e.key === 'Escape' && document.getElementById('v12AssetDialog')) { e.preventDefault(); e.stopImmediatePropagation(); v12CloseDialog() } }, true);
function v12Migrate() { if (state.v12MediaOrganizer) return; state.media.forEach(m => { m.displayName ??= m.name; let old = (m.tag || '').trim(); m.collection ??= (['Founder story', 'ADHD', 'Business', 'Mindset', 'Dogs', 'Relationships', 'Lifestyle'].includes(old) ? old : 'Unsorted'); m.tags ??= (old && !['New upload'].includes(old) ? [old] : []); m.notes ??= ''; m.linkedPostIds ??= [] }); state.v12MediaOrganizer = 1; save() }
v12Migrate();

// Changes to Naomi-facing requests are still local to this browser until Supabase is connected.
v11Migrate();

// Make preview notes explicit and initialise the rule-based suggestion queue once.
if (!state.v10ScanVersion) v10ScanAll(false);
v10RestoreBlobs(); render();